using FluentValidation;using Microsoft.EntityFrameworkCore;using SchoolERP.Application.Abstractions;using SchoolERP.Application.Common.Extensions;using SchoolERP.Application.Common.Pagination;using SchoolERP.Application.Exceptions;using SchoolERP.Application.Features.Schools;using SchoolERP.Domain.Entities;using SchoolERP.Domain.Enums;
namespace SchoolERP.Application.Features.ClassSections;
public sealed class ClassSectionService(IApplicationDbContext db,ICurrentSchoolResolver current,IValidator<CreateClassSectionRequest>cv,IValidator<UpdateClassSectionRequest>uv,IValidator<ChangeClassSectionCodeRequest>ccv,TimeProvider clock):IClassSectionService{
 public async Task<PagedResult<ClassSectionListItemDto>>ListAsync(GetClassSectionsQuery r,CancellationToken ct=default){var sid=await current.ResolveAsync(ct);if(r.SchoolClassId.HasValue){var parent=await db.SchoolClasses.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==r.SchoolClassId&&x.SchoolId==sid,ct)??throw new ResourceNotFoundException("Class");if(r.AcademicYearId.HasValue&&parent.AcademicYearId!=r.AcademicYearId)throw new ResourceNotFoundException("Class");}else if(r.AcademicYearId.HasValue&&!await db.AcademicYears.AsNoTracking().AnyAsync(x=>x.Id==r.AcademicYearId&&x.SchoolId==sid,ct))throw new ResourceNotFoundException("Academic year");var q=db.ClassSections.AsNoTracking().Where(x=>x.SchoolId==sid).WhereIf(r.AcademicYearId.HasValue,x=>x.AcademicYearId==r.AcademicYearId).WhereIf(r.SchoolClassId.HasValue,x=>x.SchoolClassId==r.SchoolClassId).WhereIf(r.Status.HasValue,x=>x.Status==r.Status);if(!string.IsNullOrWhiteSpace(r.Search)){var t=r.Search.Trim().ToLower();q=q.Where(x=>x.Name.ToLower().Contains(t)||x.Code.ToLower().Contains(t)||(x.ShortName!=null&&x.ShortName.ToLower().Contains(t))||(x.RoomNumber!=null&&x.RoomNumber.ToLower().Contains(t)));}var d=string.Equals(r.SortDirection,"desc",StringComparison.OrdinalIgnoreCase);q=(r.SortBy?.ToLowerInvariant(),d) switch{("name",false)=>q.OrderBy(x=>x.Name),("name",true)=>q.OrderByDescending(x=>x.Name),("code",false)=>q.OrderBy(x=>x.Code),("code",true)=>q.OrderByDescending(x=>x.Code),("status",false)=>q.OrderBy(x=>x.Status),("status",true)=>q.OrderByDescending(x=>x.Status),("capacity",false)=>q.OrderBy(x=>x.Capacity),("capacity",true)=>q.OrderByDescending(x=>x.Capacity),("createdat",false)=>q.OrderBy(x=>x.CreatedAt),("createdat",true)=>q.OrderByDescending(x=>x.CreatedAt),(_,true)=>q.OrderByDescending(x=>x.SchoolClass.DisplayOrder).ThenByDescending(x=>x.DisplayOrder),_=>q.OrderBy(x=>x.SchoolClass.DisplayOrder).ThenBy(x=>x.DisplayOrder).ThenBy(x=>x.Name)};return await q.Select(x=>new ClassSectionListItemDto(x.Id,x.SchoolClassId,x.SchoolClass.Name,x.SchoolClass.Code,x.AcademicYearId,x.AcademicYear.Name,x.Name,x.Code,x.ShortName,x.DisplayOrder,x.Capacity,x.RoomNumber,x.Status,x.CreatedAt,x.UpdatedAt)).ToPagedResultAsync(new(r.PageNumber,r.PageSize),ct);}
 public Task<PagedResult<ClassSectionListItemDto>>ListForClassAsync(Guid id,GetClassSectionsQuery q,CancellationToken ct=default)=>ListAsync(q with{SchoolClassId=id},ct);
 public async Task<ClassSectionDetailsDto?>GetAsync(Guid id,CancellationToken ct=default){var sid=await current.ResolveAsync(ct);return await db.ClassSections.AsNoTracking().Where(x=>x.Id==id&&x.SchoolId==sid).Select(x=>new ClassSectionDetailsDto(x.Id,x.SchoolClassId,x.SchoolClass.Name,x.SchoolClass.Code,x.AcademicYearId,x.AcademicYear.Name,x.AcademicYear.Code,x.Name,x.Code,x.ShortName,x.DisplayOrder,x.Capacity,x.RoomNumber,x.Description,x.Status,x.ActivatedAt,x.DeactivatedAt,x.ArchivedAt,x.CreatedAt,x.UpdatedAt)).SingleOrDefaultAsync(ct);}
 public async Task<ClassSectionDetailsDto>CreateAsync(Guid classId,CreateClassSectionRequest r,CancellationToken ct=default){await cv.ValidateAndThrowAsync(r,ct);var sid=await current.ResolveAsync(ct);var p=await db.SchoolClasses.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==classId&&x.SchoolId==sid,ct)??throw new ResourceNotFoundException("Class");await Parents(p,false,ct);await Unique(p.Id,r.Code,r.Name,null,ct);var x=ClassSection.Create(p.TenantId,p.SchoolId,p.AcademicYearId,p.Id,r.Name,r.Code,r.DisplayOrder,r.Capacity,r.ShortName,r.RoomNumber,r.Description,Now());db.ClassSections.Add(x);await db.SaveChangesAsync(ct);return(await GetAsync(x.Id,ct))!;}
 public async Task<ClassSectionDetailsDto?>UpdateAsync(Guid id,UpdateClassSectionRequest r,CancellationToken ct=default){await uv.ValidateAndThrowAsync(r,ct);var x=await Write(id,ct);if(x is null)return null;await Parents(x.SchoolClass,false,ct);await Unique(x.SchoolClassId,x.Code,r.Name,id,ct);x.UpdateDetails(r.Name,r.ShortName,r.DisplayOrder,r.Capacity,r.RoomNumber,r.Description,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}public async Task<ClassSectionDetailsDto?>ChangeCodeAsync(Guid id,ChangeClassSectionCodeRequest r,CancellationToken ct=default){await ccv.ValidateAndThrowAsync(r,ct);var x=await Write(id,ct);if(x is null)return null;await Parents(x.SchoolClass,false,ct);await Unique(x.SchoolClassId,r.Code,x.Name,id,ct);x.ChangeCode(r.Code,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}
 public Task<ClassSectionDetailsDto?>ActivateAsync(Guid id,CancellationToken ct=default)=>Change(id,(x,n)=>x.Activate(n),true,ct);public Task<ClassSectionDetailsDto?>DeactivateAsync(Guid id,CancellationToken ct=default)=>Change(id,(x,n)=>x.Deactivate(n),false,ct);public Task<ClassSectionDetailsDto?>ArchiveAsync(Guid id,CancellationToken ct=default)=>Change(id,(x,n)=>x.Archive(n),false,ct);
 private async Task<ClassSectionDetailsDto?>Change(Guid id,Action<ClassSection,DateTime>a,bool activate,CancellationToken ct){var x=await Write(id,ct);if(x is null)return null;await Parents(x.SchoolClass,activate,ct);a(x,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}private async Task<ClassSection?>Write(Guid id,CancellationToken ct){var sid=await current.ResolveAsync(ct);return await db.ClassSections.Include(x=>x.SchoolClass).SingleOrDefaultAsync(x=>x.Id==id&&x.SchoolId==sid,ct);}private async Task Parents(SchoolClass p,bool activation,CancellationToken ct){var schoolOk=await db.Schools.AsNoTracking().AnyAsync(s=>s.Id==p.SchoolId&&(s.Status==SchoolStatus.Draft||s.Status==SchoolStatus.Active),ct);if(!schoolOk)throw new ParentNotOperationalException("School structure cannot be changed while suspended or archived.");var y=await db.AcademicYears.AsNoTracking().SingleAsync(x=>x.Id==p.AcademicYearId&&x.SchoolId==p.SchoolId,ct);if(activation&&(p.Status!=SchoolClassStatus.Active||y.Status!=AcademicYearStatus.Active))throw new ClassSectionParentUnavailableException();if(!activation&&(p.Status is SchoolClassStatus.Inactive or SchoolClassStatus.Archived))throw new ClassSectionParentUnavailableException();if(y.Status is AcademicYearStatus.Closed or AcademicYearStatus.Archived)throw new ClassSectionParentUnavailableException("Section.AcademicYearUnavailable");}private async Task Unique(Guid c,string code,string name,Guid? except,CancellationToken ct){var normalized=ClassSection.NormalizeCode(code);var n=name.Trim().ToLower();if(await db.ClassSections.AsNoTracking().AnyAsync(x=>x.SchoolClassId==c&&x.Code==normalized&&(!except.HasValue||x.Id!=except),ct))throw new ClassSectionCodeConflictException();if(await db.ClassSections.AsNoTracking().AnyAsync(x=>x.SchoolClassId==c&&x.Name.ToLower()==n&&(!except.HasValue||x.Id!=except),ct))throw new ClassSectionNameConflictException();}private DateTime Now()=>clock.GetUtcNow().UtcDateTime;}
